// The language CHANGED WHILE PLAYING, in Chrome: on every page and tab of a career in progress the language is switched Italian → English → Italian without reloading, and the screen must follow each time
// (English: no Italian left; back to Italian: the same texts as before and no English left). Also the screens that open on top (menu, pop-ups) and the content generated by playing (campaign, offices, elections).
//   LIVE_LEVELS=deputato,comunale  LIVE_WEEKS=20  LIVE_OUT=file
import assert from 'node:assert/strict';
import { writeFileSync, readFileSync, readdirSync } from 'node:fs';
import { withBrowser, createCareerInPage, openCareer, chromeAvailable } from './lib/browser.mjs';
import { COLLECT, PAGES } from './lib/i18n-tour.mjs';
import { createIndependentDetector } from './lib/i18n-independent.mjs';

if (!chromeAvailable) { console.log('Cambio lingua dal vivo saltato: Chrome non trovato (imposta CHROME_PATH).'); process.exit(0); }
const detector = createIndependentDetector();
const levels = (process.env.LIVE_LEVELS ?? 'deputato,comunale').split(',');
const weeks = Number(process.env.LIVE_WEEKS ?? 20);
// The oracle that needs no vocabulary: a text that is IDENTICAL in the two languages on the same screen is a name, an international word, or a text nobody translated. The names are told apart by what they are
// (a Region, a party, a person, a place), the rest — every label the code itself writes, every phrase with lowercase Italian words — must differ.
const here = new URL('..', import.meta.url).pathname;
const codeLiterals = new Set();
for (const dir of ['src/ui', 'src/core', 'src/data/simulation']) for (const file of readdirSync(here + dir).filter(name => name.endsWith('.js'))) for (const match of readFileSync(`${here}${dir}/${file}`, 'utf8').matchAll(/'([^'\n\\]{3,60})'/g)) codeLiterals.add(match[1].replace(/’/g, "'"));
const SAME_OK = new Set(['Home', 'Agenda', 'Quirinale', 'QUIRINALE', 'Hall of Fame', 'POLITICANDO 2026', 'Audio', 'Volume', 'Password', 'Media', 'MEDIA', 'Welfare', 'Sport', 'Area', 'Spread', 'Deficit', 'DEFICIT', 'In deficit', 'agenda', 'scenario', 'Complete', 'Outsider', 'Afro', 'Pos.', 'Italia', 'Siena', 'Lega', 'Azione', 'Como', 'Lodi', 'Nuova', 'Sandbox', 'Account', 'ACCOUNT', 'Mar', 'Il Meridiano', 'Question time', 'Palazzo', 'Province', 'ECR', 'AGRI', 'INTA', 'ENVI', 'ECON', 'AFET', 'LIBE', 'ITRE', 'IMCO', 'TRAN', 'REGI', 'EMPL', 'CULT', 'JURI', 'DEVE', 'SEDE', 'PETI', 'BUDG', 'CONT', 'AFCO', 'FEMM', 'PECH', 'SANT', 'DROI', 'TREND', 'Trend', 'Politicando 2026, Home', 'MISTO', 'Radio', 'Social network', 'Online', 'Offline', 'Standard', 'Top', 'Totale', 'Base', 'Mix', 'Extra', 'Premium', 'Welfare', 'Europa', 'Lazio', 'Marche', 'Veneto', 'Piemonte', 'Lombardia', 'Toscana', 'Sicilia', 'Sardegna', 'Puglia', 'Campania', 'Calabria', 'Basilicata', 'Molise', 'Abruzzo', 'Umbria', 'Liguria', 'Emilia-Romagna', 'Friuli-Venezia Giulia', 'Trentino-Alto Adige', 'Valle d’Aosta']);
const REGION_CODES = new Set('ABR BAS CAL CAM EMR FVG LAZ LIG LOM MAR MOL PIE PUG SAR SIC TOS TAA UMB VDA VEN'.split(' '));
const LINK = new Set(['di', 'del', 'della', 'dei', 'delle', 'degli', 'dello', 'de', 'd', 'e', 'la', 'il', 'lo', 'in', 'per', 'al', 'all', 'dal', 'con', 'su', 'a']);
// names are told apart by their shape: most of the words start with a capital letter (a party, a person, a place, a newspaper)
const isName = text => { const words = (text.match(/[\p{L}]+/gu) ?? []).filter(word => !LINK.has(word.toLowerCase())); return words.length > 1 && words.filter(word => /^\p{Lu}/u.test(word)).length / words.length > 0.6; };
const OFFICIAL = /^(?:Disposizioni|Ratifica|Conversione|Istituzione|Modifiche|Delega|Misure|Norme|Interventi|Gov\.|Pres\. |Sen\. |Dep\. )|\bed altri\b|\bdecreto[- ]legge\b/;   // titles of acts and the lists of their proposers: official Italian names, kept whole by design
const bare = text => text.replace(/[\d\s.,%€:+\-–/·()#]+/g, ' ').trim();
const untranslated = text => !SAME_OK.has(text) && !SAME_OK.has(bare(text)) && !OFFICIAL.test(text) && !REGION_CODES.has(text) && !/^[\d\s.,%€:+\-–/·()#]+$/.test(text) && !/^https?:|@/.test(text)
  && (/\s/.test(text.trim()) ? !isName(text) && /\p{Ll}{3}/u.test(text) : codeLiterals.has(text.replace(/’/g, "'")));
const problems = [], stats = { screens: 0, texts: 0 }, unchanged = new Map();   // texts that are the SAME in both languages on the same screen: translated, or a name, or left in Italian (no vocabulary decides it)
for (const level of levels) {
  await withBrowser(async ({ evaluate, goto, waitFor: wait, pause, viewport, version }) => {
    await viewport(1280, 900, false);
    await createCareerInPage({ evaluate, version }, { level, weeks, region: 'Lombardia', group: level === 'senatore' ? 'senato-xix-gruppo-56' : 'cam-xix-03', name: ['Anna', 'Bianchi'] });
    await openCareer({ evaluate, goto, waitFor: wait }); await pause(1500);
    const settled = async () => { let last = null; for (let i = 0; i < 16; i++) { const now = JSON.stringify(await evaluate(COLLECT)); if (now === last) return JSON.parse(now); last = now; await pause(250); } return JSON.parse(last); };
    const lang = async next => { await evaluate(`import('/src/core/i18n.js?v=${version}').then(m => m.setLanguage(${JSON.stringify(next)})).then(() => true)`); await pause(500); };
    const tabs = () => evaluate(`[...document.querySelectorAll('[data-section-tab]')].map(b => [b.dataset.sectionTab, b.dataset.sectionTabValue])`);
    const click = (name, value) => evaluate(`(() => { const b = [...document.querySelectorAll('[data-section-tab]')].find(x => x.dataset.sectionTab === ${JSON.stringify(name)} && x.dataset.sectionTabValue === ${JSON.stringify(value)}); if (!b) return false; b.click(); return true; })()`);
    const openAll = () => evaluate(`document.querySelectorAll('details:not([open])').forEach(d => d.setAttribute('open', '')); true`);
    const roundTrip = async screen => {
      await openAll(); await pause(150);
      const it0 = await settled();
      await lang('en'); await openAll(); await pause(200);
      const en = await settled();
      await lang('it'); await openAll(); await pause(200);
      const it1 = await settled();
      stats.screens++; stats.texts += en.length;
      const left = [...new Set(en)].map(text => [text, detector.reasonOf(text)]).filter(([, reason]) => reason);
      for (const [text, reason] of left) problems.push(`${level}/${screen} [EN] italiano rimasto: «${text.slice(0, 110)}» (${reason})`);
      const back = [...new Set(it1)].map(text => [text, detector.reasonOfEnglish(text)]).filter(([, reason]) => reason);
      for (const [text, reason] of back) problems.push(`${level}/${screen} [IT dopo EN] inglese rimasto: «${text.slice(0, 110)}» (${reason})`);
      const itSet = new Set(it0);
      for (const text of new Set(en)) if (itSet.has(text) && /\p{L}{3}/u.test(text) && untranslated(text)) { const item = unchanged.get(text) ?? new Set(); item.add(`${level}/${screen}`); unchanged.set(text, item); }
      const a = new Set(it0), b = new Set(it1);
      for (const text of b) if (!a.has(text) && !/\d/.test(text)) problems.push(`${level}/${screen} [IT dopo EN] testo diverso da prima: «${text.slice(0, 110)}»`);
    };
    for (const page of PAGES) {
      await evaluate(`location.hash = '#${page}'; true`); await pause(900);
      await roundTrip(page);
      for (const [name, value] of await tabs()) {
        if (!(await click(name, value))) continue;
        await pause(500); await roundTrip(`${page}/${value}`);
      }
    }
  }, {});
}
for (const [text, where] of unchanged) problems.push(`${[...where][0]} [EN] identico all’italiano (non tradotto o nome da dichiarare): «${text.slice(0, 100)}»`);
if (process.env.LIVE_UNCHANGED) writeFileSync(process.env.LIVE_UNCHANGED, JSON.stringify([...unchanged].map(([text, where]) => [text, [...where].slice(0, 3)]), null, 1));
if (process.env.LIVE_OUT) writeFileSync(process.env.LIVE_OUT, JSON.stringify(problems, null, 1));
console.log(`Cambio lingua dal vivo: ${stats.screens} schermate, ${stats.texts} testi inglesi analizzati, ${problems.length} problemi.`);
for (const p of problems.slice(0, 60)) console.log(' -', p);
assert.equal(problems.length, 0, `${problems.length} problemi nel cambio lingua`);
